# imperfect inverted repeats: for each i, find furthest j>i with good rc match
def hamming(a,b): return sum(x!=y for x,y in zip(a,b))
L=len(seq)
hits=[]
minstem=8
for i in range(L-minstem):
    # try stem lengths
    for stem in (8,10,12,14,16,18):
        if i+2*stem>L: continue
        a=seq[i:i+stem]; b=seq[i+stem:i+2*stem]
        mm=hamming(a, rc(b))
        if mm<=max(1,stem//8):
            hits.append((2*stem-mm,i+1,i+stem,a+"/"+b,mm))
# dedupe overlapping, keep best (largest stem)
hits.sort(key=lambda x:-x[0])
print("imperfect inverted repeats (stem>=8, <=1-2 mismatch):")
for h in hits[:25]: print(h)

